'use strict';

const fs = require('fs');
const os = require('os');
const path = require('path');
const { execFile, execSync } = require('child_process');
const { promisify } = require('util');
const cds = require('@sap/cds');

const { info, warn, dim } = require('../../../lib/util/term');

const execFileAsync = promisify(execFile);
const TIMEOUT_MS = 120_000;
const PATCH_RELATIVE_PATH = path.join('target', 'rewrite', 'rewrite.patch');

const SAP_PUBLIC_MAVEN_URL = 'https://repo.maven.apache.org/maven2';

function buildArgs(goal, settingsPath, recipeList) {
  return [
    `-gs`, settingsPath,
    '-U',
    `org.openrewrite.maven:rewrite-maven-plugin:${goal}`,
    `-Drewrite.activeRecipes=${recipeList}`,
    '-Drewrite.recipeArtifactCoordinates=com.sap.cds:cds-services-recipes:RELEASE',
  ];
}

async function runOpenRewrite(ctx) {
  const recipes = collectRecipes(ctx);
  if (recipes.length === 0) return;

  const mvn = findMvn();
  if (!mvn) {
    console.log(`  ${warn('mvn not found – OpenRewrite recipes skipped')}`);
    ctx.analysis.orSkipped = true;
    return;
  }

  const recipeList = recipes.map(r => r.orRecipe).join(',');
  const settingsPath = writeTempSettings();
  const mvnOpts = { cwd: cds.root, timeout: TIMEOUT_MS, env: { ...process.env, MAVEN_OPTS: process.env.MAVEN_OPTS || '' } };
  const args = (goal) => buildArgs(goal, settingsPath, recipeList);

  console.log(`  ${ctx.shouldFix ? 'Applying' : 'Checking'} ${recipes.length} OpenRewrite recipe${recipes.length > 1 ? 's' : ''}...`);

  try {
    // Always dry-run first to collect locations
    const dryResult = await execFileAsync(mvn, args('dryRunNoFork'), mvnOpts);
    const dryOutput = (dryResult.stdout + dryResult.stderr).trim();
    if (!dryOutput.includes('BUILD SUCCESS')) {
      console.log(`  ${warn('OpenRewrite finished without clear success signal.')}`);
      if (dryOutput) console.log(`\n${dim(dryOutput)}\n`);
      return;
    }

    const recipeFileMap = parseRecipeFileMap(dryOutput);
    const matched = recipes.filter(r => recipeFileMap.has(r.orRecipe) || dryOutput.includes(r.orRecipe));
    if (matched.length === 0) {
      console.log(`  ${info('OpenRewrite completed – no changes needed.')}`);
      return;
    }

    const patchHunks = readPatchHunks();
    addOrFindings(ctx, matched, recipeFileMap, patchHunks);

    if (ctx.shouldFix) {
      try {
        await execFileAsync(mvn, args('runNoFork'), mvnOpts);
      } catch (applyErr) {
        const msg = applyErr.killed ? 'timed out' : 'mvn exited with error';
        console.log(`  ${warn(`OpenRewrite apply failed: ${msg}`)}`);
        ctx.analysis.orApplyFailed = msg;
        return;
      }
      console.log(`  ${info(`OpenRewrite applied ${matched.length} recipe${matched.length > 1 ? 's' : ''} successfully.`)}`);
      ctx.analysis.orApplied = matched.map(r => r.orRecipe);
    } else {
      console.log(`  ${info(`OpenRewrite dry-run: ${matched.length} recipe${matched.length > 1 ? 's' : ''} would make changes.`)}`);
      ctx.analysis.orDryRun = matched.map(r => r.orRecipe);
    }
  } catch (e) {
    const errOutput = ((e.stdout || '') + (e.stderr || '')).trim();
    if (isRecipeArtifactError(errOutput)) {
      console.log(`  ${warn('OpenRewrite skipped – recipe artifact (com.sap.cds:cds-services-recipes) not found.')}`);
      console.log(`  ${dim('Ensure Maven is configured to reach the SAP public Maven repository.')}`);
      ctx.analysis.orSkipped = true;
    } else if (isPomResolutionError(errOutput)) {
      console.log(`  ${warn('OpenRewrite skipped – project POM could not be resolved.')}`);
      console.log(`  ${dim('Run mvn install first to ensure dependencies are available.')}`);
      ctx.analysis.orSkipped = true;
    } else {
      const msg = e.killed ? 'timed out' : 'mvn exited with error';
      console.log(`  ${warn(`OpenRewrite failed: ${msg}`)}`);
      if (!e.killed && errOutput) console.log(`\n${dim(errOutput)}\n`);
      ctx.analysis.orFailed = msg;
    }
  } finally {
    try { fs.unlinkSync(settingsPath); } catch { /* ignore */ }
  }
}

function collectRecipes(ctx) {
  if (!ctx.rules) return [];
  const seen = new Set();
  const recipes = [];
  for (const rule of ctx.rules) {
    if (!rule.orRecipe) continue;
    if (seen.has(rule.orRecipe)) continue;
    seen.add(rule.orRecipe);
    recipes.push(rule);
  }
  return recipes;
}

function addOrFindings(ctx, recipes, recipeFileMap, patchHunks) {
  const fileRecipeCount = new Map();
  for (const [, files] of recipeFileMap) {
    for (const file of files) {
      fileRecipeCount.set(file, (fileRecipeCount.get(file) || 0) + 1);
    }
  }

  for (const rule of recipes) {
    const files = recipeFileMap.get(rule.orRecipe) || [];
    const matches = buildMatches(files, patchHunks, fileRecipeCount);
    ctx.analysis.findings.push({
      ruleId: rule.id,
      title: rule.title,
      scope: rule.scope || [],
      group: rule.group || null,
      capireSection: rule.capireSection || null,
      guidance: rule.guidance || null,
      body: rule.body || null,
      capireAnchor: rule.capireAnchor || null,
      compilerDetects: false,
      patternsComplete: false,
      compatFlag: null,
      orRecipe: rule.orRecipe,
      coverage: 'complete',
      matches,
    });
  }
}

function buildMatches(files, patchHunks, fileRecipeCount) {
  if (files.length === 0) return [{ source: 'openrewrite' }];
  const matches = [];
  for (const file of files) {
    const isUnambiguous = (fileRecipeCount.get(file) || 0) <= 1;
    const hunks = isUnambiguous ? patchHunks.get(file) : null;
    if (hunks && hunks.length > 0) {
      for (const line of hunks) {
        matches.push({ file, line, source: 'openrewrite' });
      }
    } else {
      matches.push({ file, line: null, source: 'openrewrite' });
    }
  }
  return matches;
}

function stripAnsi(str) {
  // eslint-disable-next-line no-control-regex
  return str.replace(/\x1b\[[0-9;]*m/g, '');
}

function parseRecipeFileMap(output) {
  const map = new Map();
  const lines = stripAnsi(output).split('\n');
  for (let i = 0; i < lines.length; i++) {
    const fileMatch = lines[i].match(/These recipes would make changes to (.+?):\s*$/);
    if (!fileMatch) continue;
    const file = fileMatch[1].trim();
    for (let j = i + 1; j < lines.length; j++) {
      const recipeLine = lines[j].match(/^\s*(?:\[WARNING\]\s*)?\s{2,}(\S+)\s*$/);
      if (!recipeLine) break;
      const recipe = recipeLine[1];
      if (!map.has(recipe)) map.set(recipe, []);
      map.get(recipe).push(file);
      i = j; // advance outer loop past consumed recipe lines
    }
  }
  return map;
}

function readPatchHunks() {
  const patchFiles = findPatchFiles(cds.root);
  if (patchFiles.length === 0) return new Map();
  const combined = new Map();
  for (const patchFile of patchFiles) {
    const moduleRoot = path.dirname(path.dirname(path.dirname(patchFile)));
    const moduleDir = path.relative(cds.root, moduleRoot);
    const prefix = moduleDir === '.' ? '' : moduleDir;
    const content = readFileSafe(patchFile);
    if (!content) continue;
    const hunks = parsePatchHunks(content, prefix);
    for (const [file, lines] of hunks) {
      if (!combined.has(file)) combined.set(file, []);
      combined.get(file).push(...lines);
    }
  }
  return combined;
}

function findPatchFiles(root) {
  const results = [];
  const rootPatch = path.join(root, PATCH_RELATIVE_PATH);
  if (fileExists(rootPatch)) results.push(rootPatch);
  try {
    for (const entry of fs.readdirSync(root, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      if (entry.name === 'node_modules' || entry.name === '.git') continue;
      const modulePatch = path.join(root, entry.name, PATCH_RELATIVE_PATH);
      if (fileExists(modulePatch)) results.push(modulePatch);
    }
  } catch { /* non-fatal */ }
  return results;
}

function parsePatchHunks(content, modulePrefix) {
  const hunks = new Map();
  let currentFile = null;
  for (const line of content.split('\n')) {
    const diffHeader = line.match(/^diff --git a\/(.+?) b\//);
    if (diffHeader) {
      const relativePath = diffHeader[1];
      currentFile = modulePrefix ? path.join(modulePrefix, relativePath) : relativePath;
      continue;
    }
    if (!currentFile) continue;
    const hunkHeader = line.match(/^@@ -(\d+)/);
    if (hunkHeader) {
      const startLine = parseInt(hunkHeader[1], 10);
      if (!hunks.has(currentFile)) hunks.set(currentFile, []);
      hunks.get(currentFile).push(startLine);
    }
  }
  return hunks;
}

function readFileSafe(filePath) {
  try { return fs.readFileSync(filePath, 'utf8'); } catch { return null; }
}

function fileExists(filePath) {
  try { return fs.statSync(filePath).isFile(); } catch { return false; }
}

function writeTempSettings() {
  const content = `<settings xmlns="http://maven.apache.org/SETTINGS/1.0.0">
  <profiles>
    <profile>
      <id>cds-upgrade</id>
      <repositories>
        <repository>
          <id>maven-central</id>
          <url>${SAP_PUBLIC_MAVEN_URL}</url>
          <releases><enabled>true</enabled></releases>
          <snapshots><enabled>false</enabled></snapshots>
        </repository>
      </repositories>
    </profile>
  </profiles>
  <activeProfiles>
    <activeProfile>cds-upgrade</activeProfile>
  </activeProfiles>
</settings>`;
  const settingsPath = path.join(os.tmpdir(), `cds-upgrade-settings-${Date.now()}.xml`);
  fs.writeFileSync(settingsPath, content, 'utf8');
  return settingsPath;
}

function isRecipeArtifactError(output) {
  return /Could not find artifact.*com\.sap\.cds/.test(output);
}

function isPomResolutionError(output) {
  return /Non-resolvable.*POM/.test(output);
}

function findMvn() {
  const mvnw = path.join(cds.root, 'mvnw');
  if (cds.utils.exists(mvnw)) return mvnw;
  try {
    execSync('mvn --version', { stdio: 'ignore' });
    return 'mvn';
  } catch {
    return null;
  }
}

module.exports = { runOpenRewrite };
module.exports._test = { parseRecipeFileMap, parsePatchHunks, buildMatches };
